ALTER TABLE ONLY public.category_materials ALTER COLUMN id SET DEFAULT nextval('public.material_groups_id_seq'::regclass);
ALTER TABLE ONLY public.contaminations ALTER COLUMN id SET DEFAULT nextval('public.contaminations_id_seq'::regclass);
