-- ── ตั้ง sequence ต่อจากแถวสุดท้าย กัน id ชนตอนเพิ่มแถวใหม่ ──
SELECT setval(pg_get_serial_sequence('public.thai_geographies', 'id'), GREATEST((SELECT max(id) FROM public.thai_geographies), 1)) WHERE pg_get_serial_sequence('public.thai_geographies', 'id') IS NOT NULL;
SELECT setval(pg_get_serial_sequence('public.thai_provinces', 'id'), GREATEST((SELECT max(id) FROM public.thai_provinces), 1)) WHERE pg_get_serial_sequence('public.thai_provinces', 'id') IS NOT NULL;
