DO $seed$
DECLARE n_tambons int; n_materials int;
BEGIN
    SELECT count(*) INTO n_tambons FROM thai_tambons;
    SELECT count(*) INTO n_materials FROM materials;
    RAISE NOTICE 'seed: thai_tambons % แถว, materials % แถว', n_tambons, n_materials;
END
$seed$;